1	"use client";
2	
3	import { useEffect, useMemo, useRef, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import Link from "next/link";
6	import { ArrowLeft, ArrowRight, RotateCcw, Sparkles } from "lucide-react";
7	import { destinationAfterAuth } from "@/lib/pending-prompt";
8	import { getTemplate } from "@/lib/templates";
9	import {
10	  assemblePrompt,
11	  getLook,
12	  EMPTY_ANSWERS,
13	  hasAnswers,
14	  MAX_NAME_CHARS,
15	  MAX_WHAT_CHARS,
16	  stashPrompt,
17	  templatesForCategory,
18	  WIZARD_CATEGORIES,
19	  type WizardAnswers,
20	} from "@/lib/wizard";
21	import { factRows, SOURCE_LABELS, type FactRow } from "@/lib/site-import";
22	import { LookPicker } from "./LookPicker";
23	import {
24	  EMPTY_IMPORT,
25	  hasImport,
26	  hasImportedFacts,
27	  importFragment,
28	  ImportStep,
29	  type ImportState,
30	} from "./ImportStep";
31	
32	/**
33	 * The prompt wizard.
34	 *
35	 * ## It is a side door, never a gate
36	 *
37	 * The raw composer on the home page is and stays the default: nothing here
38	 * blocks it, nothing here renders on it, and a returning user never sees this
39	 * unless they ask for it. Everything below is skippable — the two question
40	 * screens each carry a Skip, and "Skip to the prompt" on either of them jumps
41	 * straight to the review with whatever has been answered so far. Abandoning
42	 * halfway is a productive action, not a loss.
43	 *
44	 * ## Zero model calls, and — signed out — zero server calls
45	 *
46	 * Assembly is local string work in lib/wizard.ts and lib/site-import.ts. There
47	 * is no /api/enhance call here and there should not be one: that route is
48	 * auth-gated and rate limited per user id, and most people meeting this wizard
49	 * are signed out.
50	 *
51	 * Step 3 is the only place that can touch a server at all, and only on the URL
52	 * path, which is rendered only for a signed-in user on a deployment where the
53	 * isolated egress fetcher is switched on. The paste box next to it parses in
54	 * the browser and always works.
55	 *
56	 * ## Imported facts get a second look before anything is built
57	 *
58	 * A prompt someone typed themselves is theirs, and the editor firing it
59	 * automatically after signup is right. A prompt carrying an address and a phone
60	 * number scraped off a web page is different: the failure mode is a
61	 * published-quality page asserting details the user never read, which turns the
62	 * never-invent-facts rule from a safeguard into a laundering step. So when the
63	 * prompt carries imported facts, the review step lists them and Build stays
64	 * disabled until the user says they have checked them.
65	 *
66	 * That closes the wizard's own path. It does NOT close the editor's:
67	 * app/projects/[id]/Editor.tsx still auto-fires whatever is in sessionStorage
68	 * on arrival, and giving it a "we pulled this from your site — check it" strip
69	 * is a change to files outside this one's scope. Until that exists, the
70	 * confirmation below is the only gate, and it is a real one — the facts are on
71	 * screen, individually toggleable one step back, and inside the prompt textarea
72	 * in full.
73	 */
74	
75	const STEPS = [
76	  { id: "what", label: "What and who" },
77	  { id: "look", label: "Pick a look" },
78	  { id: "bring", label: "What you have" },
79	  { id: "review", label: "Your prompt" },
80	] as const;
81	
82	const LAST = STEPS.length - 1;
83	
84	export function PromptWizard({
85	  signedIn,
86	  creditEstimate,
87	  urlImport = false,
88	}: {
89	  signedIn: boolean;
90	  /** From estimateCredits("create") on the server — lib/credits.ts pulls in Prisma. */
91	  creditEstimate: { low: number; high: number };
92	  /**
93	   * Is the isolated egress fetcher switched on for this deployment?
94	   *
95	   * Defaults to false so that a caller who has not thought about it gets the
96	   * safe answer, which is also the answer the server gives: the route refuses
97	   * with a 503 unless KODELY_SITE_IMPORT_EGRESS is set. With this false the URL
98	   * fields are not rendered at all and step 3 is the paste box, which needs
99	   * neither a server nor an account.
100	   */
101	  urlImport?: boolean;
102	}) {
103	  const router = useRouter();
104	  const [step, setStep] = useState(0);
105	  const [answers, setAnswers] = useState<WizardAnswers>(EMPTY_ANSWERS);
106	  const [imports, setImports] = useState<ImportState>(EMPTY_IMPORT);
107	  /** Non-null once the review textarea has been touched. This is what Revert throws away. */
108	  const [edited, setEdited] = useState<string | null>(null);
109	  /** Ticked on the review step. Only ever required when facts were imported. */
110	  const [factsChecked, setFactsChecked] = useState(false);
111	  const [starting, setStarting] = useState(false);
112	  const [error, setError] = useState<string | null>(null);
113	  const headingRef = useRef<HTMLHeadingElement>(null);
114	  /** Skip the focus move on first paint — nobody asked to be sent anywhere yet. */
115	  const mounted = useRef(false);
116	
117	  const assembled = useMemo(() => {
118	    const base = assemblePrompt(answers);
119	    const brought = importFragment(imports, Boolean(answers.lookId));
120	    return brought ? `${base}\n\n${brought}` : base;
121	  }, [answers, imports]);
122	  const promptText = edited ?? assembled;
123	  const matches = templatesForCategory(answers.category);
124	
125	  const importedRows = factRows(imports.facts).filter((r) => !imports.excluded.includes(r.key));
126	  /** The build gate. Nothing imported means nothing extra to confirm. */
127	  const needsFactCheck = hasImportedFacts(imports);
128	
129	  // Moving between steps swaps the whole panel, so without this a keyboard or
130	  // screen-reader user is left focused on a button that no longer means what it
131	  // did. The sr-only status region below announces the change; this puts the
132	  // caret where the new content starts.
133	  useEffect(() => {
134	    if (!mounted.current) {
135	      mounted.current = true;
136	      return;
137	    }
138	    headingRef.current?.focus();
139	  }, [step]);
140	
141	  /**
142	   * Any change to an answer invalidates a hand-edit of the assembled prompt —
143	   * silently keeping the old text would mean the palette they just changed
144	   * never reaches the build. Dropping the edit is the honest failure: the
145	   * review step is right there and the edit was one screen ago.
146	   */
147	  function update(patch: Partial<WizardAnswers>) {
148	    setAnswers((prev) => ({ ...prev, ...patch }));
149	    setEdited(null);
150	  }
151	
152	  /**
153	   * Same contract as `update`, and one addition: any change to what was
154	   * imported drops the "I've checked these" tick. A confirmation that survives
155	   * the thing it confirmed changing is not a confirmation.
156	   */
157	  function updateImports(next: ImportState) {
158	    setImports(next);
159	    setEdited(null);
160	    setFactsChecked(false);
161	  }
162	
163	  function pickCategory(category: WizardAnswers["category"]) {
164	    const first = templatesForCategory(category)[0];
165	    update({ category, templateId: first?.id ?? null });
166	  }
167	
168	  /**
169	   * Skip means skip: it clears whatever this screen contributed and moves on,
170	   * rather than quietly keeping a half-answer the user just decided against.
171	   * Step 1's fields are all optional, so there is nothing to clear there — it
172	   * is the same as Next, and having the control present matters more than
173	   * having it do something different.
174	   */
175	  function skip() {
176	    if (step === 1) update({ lookId: null });
177	    if (step === 2) updateImports(EMPTY_IMPORT);
178	    setStep((s) => s + 1);
179	  }
180	
181	  async function build() {
182	    if (starting) return;
183	    // Belt and braces: the button is already disabled, but this is the one
184	    // condition where a stale click must not start a build.
185	    if (needsFactCheck && !factsChecked) return;
186	    const text = promptText.trim();
187	    if (!text) return;
188	
189	    setStarting(true);
190	    setError(null);
191	
192	    // Hand off through the SAME pending-prompt mechanism the composer and the
193	    // template gallery use, rather than inventing a second route into a build.
194	    // Signed out: /signup shows the prompt back and its submit handler calls
195	    // destinationAfterAuth(). Signed in: we call it directly.
196	    if (!stashPrompt(text)) {
197	      setStarting(false);
198	      setError(
199	        "Your browser is blocking session storage, so the prompt can't travel with you. Copy it somewhere safe first, or try a normal (non-private) window.",
200	      );
201	      return;
202	    }
203	
204	    if (!signedIn) {
205	      router.push("/signup");
206	      return;
207	    }
208	
209	    // Returns "/dashboard" if project creation fails, including a session that
210	    // expired since this page rendered — the prompt stays in sessionStorage
211	    // either way, so nothing is lost. `starting` is deliberately left set:
212	    // every branch navigates, and a locked button stops a double-click
213	    // creating two projects.
214	    const dest = await destinationAfterAuth();
215	    router.push(dest);
216	    router.refresh();
217	  }
218	
219	  return (
220	    <div className="mx-auto w-full max-w-3xl">
221	      {/* Step changes are a whole-panel swap with no page navigation, so they
222	          are invisible to assistive tech unless announced. */}
223	      <p role="status" className="sr-only">
224	        {`Step ${step + 1} of ${STEPS.length}: ${STEPS[step].label}.`}
225	      </p>
226	
227	      <div className="rounded-2xl border border-black/10 bg-white/60 p-6 backdrop-blur-sm sm:p-8 dark:border-white/10 dark:bg-white/[0.02]">
228	        <div className="flex flex-wrap items-center justify-between gap-3">
229	          <p
230	            aria-hidden
231	            className="text-[11px] font-medium uppercase tracking-[0.14em] text-neutral-500 dark:text-neutral-400"
232	          >
233	            Step {step + 1} of {STEPS.length} · {STEPS[step].label}
234	          </p>
235	          <div aria-hidden className="flex items-center gap-1.5">
236	            {STEPS.map((s, i) => (
237	              <span
238	                key={s.id}
239	                className={`h-1.5 rounded-full transition-all ${
240	                  i === step
241	                    ? "w-6 bg-neutral-900 dark:bg-white"
242	                    : i < step
243	                      ? "w-1.5 bg-neutral-900/40 dark:bg-white/40"
244	                      : "w-1.5 bg-black/10 dark:bg-white/15"
245	                }`}
246	              />
247	            ))}
248	          </div>
249	        </div>
250	
251	        {step === 0 && (
252	          <WhatStep
253	            headingRef={headingRef}
254	            answers={answers}
255	            matches={matches}
256	            onPickCategory={pickCategory}
257	            onUpdate={update}
258	          />
259	        )}
260	
261	        {step === 1 && (
262	          <section className="mt-6">
263	            <h2
264	              ref={headingRef}
265	              tabIndex={-1}
266	              className="text-xl font-semibold tracking-tight outline-none focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[var(--accent)]"
267	            >
268	              Pick a look
269	            </h2>
270	            <div className="mt-5">
271	              <LookPicker value={answers.lookId} onChange={(lookId) => update({ lookId })} />
272	            </div>
273	          </section>
274	        )}
275	
276	        {step === 2 && (
277	          <ImportStep
278	            headingRef={headingRef}
279	            state={imports}
280	            onChange={updateImports}
281	            signedIn={signedIn}
282	            urlImport={urlImport}
283	          />
284	        )}
285	
286	        {step === 3 && (
287	          <ReviewStep
288	            headingRef={headingRef}
289	            promptText={promptText}
290	            basis={{
291	              template: (answers.templateId ? getTemplate(answers.templateId) : undefined)?.name ?? null,
292	              look: (answers.lookId ? getLook(answers.lookId) : undefined)?.name ?? null,
293	              imported: hasImport(imports) ? (imports.facts.origin ?? "what you pasted") : null,
294	            }}
295	            importedRows={importedRows}
296	            needsFactCheck={needsFactCheck}
297	            factsChecked={factsChecked}
298	            onFactsChecked={setFactsChecked}
299	            edited={edited}
300	            onEdit={setEdited}
301	            onRevert={() => setEdited(null)}
302	            creditEstimate={creditEstimate}
303	            signedIn={signedIn}
304	            starting={starting}
305	            error={error}
306	            onBuild={build}
307	          />
308	        )}
309	
310	        {/* ── Navigation ─────────────────────────────────────────────────── */}
311	        <div className="mt-8 flex flex-col gap-3 border-t border-black/10 pt-6 sm:flex-row sm:items-center sm:justify-between dark:border-white/10">
312	          <div className="flex items-center gap-3">
313	            {step > 0 && (
314	              <button
315	                type="button"
316	                onClick={() => setStep((s) => s - 1)}
317	                className="inline-flex items-center gap-1.5 rounded-lg px-3 py-2 text-sm font-medium text-neutral-600 transition-colors hover:bg-black/5 hover:text-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
318	              >
319	                <ArrowLeft size={14} aria-hidden />
320	                Back
321	              </button>
322	            )}
323	            {/* Only on the first screen. On the second, "Skip this step" already
324	                lands on the review, so a second control saying almost the same
325	                thing would just be two ways to guess. */}
326	            {step === 0 && (
327	              <button
328	                type="button"
329	                onClick={() => setStep(LAST)}
330	                className="rounded-lg px-3 py-2 text-sm text-neutral-500 underline underline-offset-4 transition-colors hover:text-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:text-neutral-400 dark:hover:text-white"
331	              >
332	                Skip to the prompt
333	              </button>
334	            )}
335	          </div>
336	
337	          {step < LAST && (
338	            <div className="flex items-center gap-2">
339	              <button
340	                type="button"
341	                onClick={skip}
342	                className="rounded-lg px-3 py-2 text-sm font-medium text-neutral-600 transition-colors hover:bg-black/5 hover:text-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
343	              >
344	                Skip this step
345	              </button>
346	              <button
347	                type="button"
348	                onClick={() => setStep((s) => s + 1)}
349	                className="group inline-flex items-center justify-center gap-2 rounded-lg bg-neutral-900 px-5 py-2.5 text-sm font-medium text-white transition-colors hover:bg-neutral-800 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:bg-white dark:text-neutral-900 dark:hover:bg-neutral-200"
350	              >
351	                Next
352	                <ArrowRight
353	                  size={14}
354	                  aria-hidden
355	                  className="transition-transform group-hover:translate-x-0.5"
356	                />
357	              </button>
358	            </div>
359	          )}
360	        </div>
361	      </div>
362	
363	      {/* The way out. Leaving is never a loss of work while there is any: the
364	          skip controls above hand back everything answered so far as a finished
365	          prompt, and this link goes to the plain box, which is the default entry
366	          point and always was. */}
367	      <p className="mt-5 text-center text-xs text-neutral-500 dark:text-neutral-400">
368	        {hasAnswers(answers) && step < LAST ? (
369	          <>Done answering? Skip ahead for the prompt, or </>
370	        ) : (
371	          <>Would rather just type it? </>
372	        )}
373	        <Link
374	          href="/"
375	          className="underline underline-offset-4 transition-colors hover:text-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:hover:text-white"
376	        >
377	          go back to the plain box
378	        </Link>
379	        .
380	      </p>
381	    </div>
382	  );
383	}
384	
385	// ---------------------------------------------------------------------------
386	// Step 1 — what and who
387	// ---------------------------------------------------------------------------
388	
389	function WhatStep({
390	  headingRef,
391	  answers,
392	  matches,
393	  onPickCategory,
394	  onUpdate,
395	}: {
396	  headingRef: React.RefObject<HTMLHeadingElement | null>;
397	  answers: WizardAnswers;
398	  matches: ReturnType<typeof templatesForCategory>;
399	  onPickCategory: (category: WizardAnswers["category"]) => void;
400	  onUpdate: (patch: Partial<WizardAnswers>) => void;
401	}) {
402	  return (
403	    <section className="mt-6">
404	      <h2
405	        ref={headingRef}
406	        tabIndex={-1}
407	        className="text-xl font-semibold tracking-tight outline-none focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[var(--accent)]"
408	      >
409	        What are you building, and who for?
410	      </h2>
411	
412	      <fieldset className="mt-6">
413	        <legend className="text-sm font-medium">What kind of site is this?</legend>
414	        <p className="mt-1.5 text-sm leading-relaxed text-neutral-600 dark:text-neutral-400">
415	          Kodely loads a starting brief written for that kind of business — the same ones on the{" "}
416	          <Link
417	            href="/templates"
418	            className="underline underline-offset-4 hover:text-neutral-900 dark:hover:text-white"
419	          >
420	            templates page
421	          </Link>
422	          . You read and edit the whole thing at the end.
423	        </p>
424	        <div className="mt-4 flex flex-wrap gap-2">
425	          {WIZARD_CATEGORIES.map((option) => (
426	            <label key={option} className="cursor-pointer">
427	              <input
428	                type="radio"
429	                name="wizard-category"
430	                value={option}
431	                checked={answers.category === option}
432	                onChange={() => onPickCategory(option)}
433	                className="peer sr-only"
434	              />
435	              <span className="inline-flex items-center rounded-full border border-neutral-200 bg-white/50 px-3.5 py-1.5 text-xs text-neutral-600 backdrop-blur-md transition-colors hover:border-neutral-300 hover:text-neutral-900 peer-checked:border-neutral-900 peer-checked:bg-neutral-900 peer-checked:text-white peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-[var(--accent)] dark:border-white/10 dark:bg-white/[0.04] dark:text-neutral-400 dark:hover:text-white dark:peer-checked:border-white dark:peer-checked:bg-white dark:peer-checked:text-neutral-900">
436	                {option}
437	              </span>
438	            </label>
439	          ))}
440	        </div>
441	      </fieldset>
442	
443	      {/* Only when the category holds more than one starter brief. With a
444	          single match it is already selected and asking would be busywork.
445	
446	          The first one is pre-selected rather than left blank: a specific brief
447	          is the whole reason the gallery and the wizard are one feature. But a
448	          pre-selection nobody notices is how a pilates studio ends up with the
449	          barbershop brief, so it is stated out loud below and the choice is one
450	          click away. */}
451	      {matches.length > 1 && (
452	        <fieldset className="mt-6">
453	          <legend className="text-sm font-medium">Which is closest?</legend>
454	          <p className="mt-1.5 text-sm leading-relaxed text-neutral-600 dark:text-neutral-400">
455	            This picks the starting brief. Change it if the highlighted one is not you.
456	          </p>
457	          <div className="mt-3 flex flex-wrap gap-2">
458	            {matches.map((template) => (
459	              <label key={template.id} className="cursor-pointer">
460	                <input
461	                  type="radio"
462	                  name="wizard-template"
463	                  value={template.id}
464	                  checked={answers.templateId === template.id}
465	                  onChange={() => onUpdate({ templateId: template.id })}
466	                  className="peer sr-only"
467	                />
468	                <span className="inline-flex items-center rounded-full border border-neutral-200 bg-white/50 px-3.5 py-1.5 text-xs text-neutral-600 transition-colors hover:border-neutral-300 hover:text-neutral-900 peer-checked:border-neutral-900 peer-checked:bg-neutral-900 peer-checked:text-white peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-[var(--accent)] dark:border-white/10 dark:bg-white/[0.04] dark:text-neutral-400 dark:hover:text-white dark:peer-checked:border-white dark:peer-checked:bg-white dark:peer-checked:text-neutral-900">
469	                  {template.name}
470	                </span>
471	              </label>
472	            ))}
473	          </div>
474	        </fieldset>
475	      )}
476	
477	      <div className="mt-6 grid gap-5 sm:grid-cols-2">
478	        <div>
479	          <label htmlFor="wizard-name" className="block text-sm font-medium">
480	            Site or business name{" "}
481	            <span className="font-normal text-neutral-500 dark:text-neutral-400">(optional)</span>
482	          </label>
483	          <input
484	            id="wizard-name"
485	            type="text"
486	            value={answers.businessName}
487	            maxLength={MAX_NAME_CHARS}
488	            onChange={(e) => onUpdate({ businessName: e.target.value })}
489	            placeholder="Bloom Pilates"
490	            className="mt-2 w-full rounded-xl border border-black/10 bg-white px-3.5 py-2.5 text-sm outline-none transition-colors placeholder:text-neutral-500 focus:border-neutral-400 focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-[var(--accent)] dark:border-white/10 dark:bg-neutral-950 dark:placeholder:text-neutral-400 dark:focus:border-neutral-600"
491	          />
492	          <p className="mt-1.5 text-xs text-neutral-500 dark:text-neutral-400">
493	            Not named it yet? Leave it — the brief says [your business name] instead.
494	          </p>
495	        </div>
496	
497	        <div>
498	          <label htmlFor="wizard-what" className="block text-sm font-medium">
499	            What do you actually do?{" "}
500	            <span className="font-normal text-neutral-500 dark:text-neutral-400">(optional)</span>
501	          </label>
502	          <input
503	            id="wizard-what"
504	            type="text"
505	            value={answers.whatYouDo}
506	            maxLength={MAX_WHAT_CHARS}
507	            onChange={(e) => onUpdate({ whatYouDo: e.target.value })}
508	            placeholder="a reformer pilates studio in Denver"
509	            className="mt-2 w-full rounded-xl border border-black/10 bg-white px-3.5 py-2.5 text-sm outline-none transition-colors placeholder:text-neutral-500 focus:border-neutral-400 focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-[var(--accent)] dark:border-white/10 dark:bg-neutral-950 dark:placeholder:text-neutral-400 dark:focus:border-neutral-600"
510	          />
511	          <p className="mt-1.5 text-xs text-neutral-500 dark:text-neutral-400">
512	            One line. It becomes the first sentence of the brief.
513	          </p>
514	        </div>
515	      </div>
516	    </section>
517	  );
518	}
519	
520	// ---------------------------------------------------------------------------
521	// Step 3 — review
522	// ---------------------------------------------------------------------------
523	
524	function ReviewStep({
525	  headingRef,
526	  promptText,
527	  basis,
528	  importedRows,
529	  needsFactCheck,
530	  factsChecked,
531	  onFactsChecked,
532	  edited,
533	  onEdit,
534	  onRevert,
535	  creditEstimate,
536	  signedIn,
537	  starting,
538	  error,
539	  onBuild,
540	}: {
541	  headingRef: React.RefObject<HTMLHeadingElement | null>;
542	  promptText: string;
543	  /** What the prompt was built from, so a wrong pick is caught before spending. */
544	  basis: { template: string | null; look: string | null; imported: string | null };
545	  /** Facts that survived step 3's tickboxes and are going into the build. */
546	  importedRows: FactRow[];
547	  needsFactCheck: boolean;
548	  factsChecked: boolean;
549	  onFactsChecked: (next: boolean) => void;
550	  edited: string | null;
