368	  if (!/^\/[A-Za-z0-9\-._~!$&'()*+,;=:@%/?#]*$/.test(raw)) return null;
369	  if (raw.startsWith("//")) return null;
370	  return `${base}${raw.slice(1)}`;
371	}
