410	function submissionEmail(input: {
411	  projectName: string;
412	  projectId: string;
413	  formName: string;
414	  fields: Record<string, string>;
415	}): { subject: string; text: string; html: string } {
416	  const name = headerSafe(input.projectName, 80) || "your site";
417	  const inbox = `${appUrl()}/projects/${encodeURIComponent(input.projectId)}/submissions`;
418	  const entries = Object.entries(input.fields);
419	
420	  const text = [
421	    `Someone filled in the "${headerSafe(input.formName, 32)}" form on ${name}.`,
422	    "",
423	    ...entries.map(([k, v]) => `${k}:\n${v}`),
424	    "",
425	    `All submissions: ${inbox}`,
426	    "",
427	    "--",
428	    "You're receiving this because it concerns your own Kodely account.",
429	    "We only send email about your account — never marketing.",
430	  ].join("\n");
431	
432	  const rows = entries
433	    .map(
434	      ([k, v]) =>
435	        `<tr><td style="padding:6px 12px 6px 0;vertical-align:top;font-size:13px;color:#6b7280;white-space:nowrap;">${escapeHtml(
436	          k,
437	        )}</td><td style="padding:6px 0;font-size:15px;line-height:1.6;color:#111111;white-space:pre-wrap;">${escapeHtml(
438	          v,
439	        )}</td></tr>`,
440	    )
441	    .join("");
442	
443	  const html = `<!doctype html>
444	<html lang="en">
445	  <head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>New form submission</title></head>
446	  <body style="margin:0;padding:24px;background:#f6f7f8;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#111111;">
447	    <div style="max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;padding:28px;">
448	      <p style="margin:0 0 20px 0;font-size:14px;font-weight:600;letter-spacing:-0.01em;color:#111111;">kodely</p>
449	      <p style="margin:0 0 16px 0;font-size:15px;line-height:1.6;">Someone filled in the &quot;${escapeHtml(
450	        input.formName,
451	      )}&quot; form on ${escapeHtml(name)}.</p>
452	      <table style="width:100%;border-collapse:collapse;margin:0 0 20px 0;">${rows}</table>
453	      <p style="margin:0;"><a href="${escapeHtml(
454	        inbox,
455	      )}" style="display:inline-block;padding:10px 18px;background:#111111;color:#ffffff;text-decoration:none;border-radius:8px;font-size:15px;font-weight:600;">All submissions</a></p>
456	      <p style="margin:24px 0 0 0;padding-top:16px;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.5;color:#6b7280;">You&#39;re receiving this because it concerns your own Kodely account. We only send email about your account — never marketing.</p>
457	    </div>
458	  </body>
459	</html>
460	`;
461	
462	  return { subject: `New ${headerSafe(input.formName, 32)} submission — ${name}`, text, html };
463	}
