465	/**
466	 * Best effort, always. The submission is already committed before this is
467	 * called and nothing here can undo that: a dead SMTP server, a bad address or a
468	 * hung connection loses an email, never an enquiry. Same guarantee as
469	 * lib/notifications/send.ts, which is why this returns void and swallows.
470	 */
471	function notifyOwner(input: {
472	  to: string;
473	  projectName: string;
474	  projectId: string;
475	  formName: string;
476	  fields: Record<string, string>;
477	}): void {
478	  if (process.env.KODELY_NOTIFY_DISABLED === "1") return;
479	  if (!isMailConfigured()) return;
480	
481	  const email = submissionEmail(input);
482	  const replyTo = replyToFor(input.fields);
483	
484	  void sendMail({
485	    to: input.to,
486	    subject: headerSafe(email.subject, 200),
487	    ...(replyTo ? { replyTo } : {}),
488	    text: email.text,
489	    html: email.html,
490	  }).catch((err) => {
491	    // Never the body, never the visitor's address — just that it failed.
492	    console.error("[site-forms] notification send failed:", err);
493	  });
494	}
