108	// ---------------------------------------------------------------------------
109	// Size caps, and the arithmetic behind them
110	// ---------------------------------------------------------------------------
111	
112	/**
113	 * TOKEN COST OF A LOGO — the numbers these caps come from.
114	 *
115	 * Base rates. The builder is claude-sonnet-5 at $3 / MTok input
116	 * (lib/models.ts, MODEL_RATES). Base64 of compressed image data is
117	 * high-entropy and tokenises at roughly 3 characters per token; SVG markup,
118	 * with its repeated tag names and digit runs, comes out slightly better at
119	 * roughly 3.2. Both are measured-ballpark, and both are conservative in the
120	 * direction that matters (they under-count tokens, so the real bill is not
121	 * worse than this).
122	 *
123	 * A logo is not paid for once. It lives in a source file, so lib/agent.ts's
124	 * describeFiles() re-sends it in the user message of EVERY turn — and the user
125	 * message is not the cached block (only SYSTEM carries cache_control). A build
126	 * runs up to 8 turns and typically 3-4, and a project has many builds.
127	 * Multiply accordingly: cost = tokens x turns x builds.
128	 *
129	 * The naive option, for scale. A 200 KB PNG dropped in unmodified:
130	 *   200 KB -> ceil(200000/3)*4 = 266,668 base64 chars
131	 *   266,668 / 3 = ~88,900 tokens
132	 *   x $3/MTok = $0.267 per turn -> ~$1.07 over a 4-turn build.
133	 * That is more than the entire rest of the build. Rejected.
134	 *
135	 * SVG cap: 12,288 characters of SANITISED markup (12 KiB).
136	 *   12,288 / 3.2 = ~3,840 tokens -> $0.0115 per turn -> ~$0.046 per 4-turn build.
137	 * Real vector logos land at 1-6 KB after sanitising strips the editor metadata,
138	 * so the cap bites only on auto-traced artwork, which is the case you want to
139	 * refuse anyway. The raw upload is allowed to be 5x that (SVG_RAW_MAX) because
140	 * Illustrator/Inkscape junk is exactly what the sanitiser deletes.
141	 *
142	 * Raster cap: 16,384 characters of data URI (16 KiB).
143	 *   16,384 / 3 = ~5,460 tokens -> $0.0164 per turn -> ~$0.066 per 4-turn build.
144	 * The UI downscales to RASTER_MAX_EDGE = 160 px before encoding, which is what
145	 * makes that cap reachable: a 160 px flat-colour logo PNG is 4-12 KB, i.e.
146	 * 5.3-16 KB of base64. 160 px renders crisply up to ~80 CSS px — a header
147	 * lockup at 2x — and a customer who wants their logo bigger than that wants SVG.
148	 *
149	 * Budget check: a build sends the whole source tree, ~15-25k tokens per turn.
150	 * At 3.8-5.5k tokens the logo is a ~20% surcharge on a first build and less
151	 * afterwards. That is the honest number; it is the price of the feature, and it
152	 * is two orders of magnitude below the naive option.
153	 */
154	export const LOGO_LIMITS = {
155	  /** Hard cap on the raw upload handed to the sanitiser. */
156	  SVG_RAW_MAX: 64 * 1024,
157	  /** Hard cap on the sanitiser's OUTPUT — the thing that actually costs tokens. */
158	  SVG_CLEAN_MAX: 12 * 1024,
159	  /** Hard cap on the whole `data:...` string. */
160	  RASTER_DATA_URI_MAX: 16 * 1024,
161	  /** Longest edge the UI downscales a raster logo to before encoding. */
162	  RASTER_MAX_EDGE: 160,
163	} as const;
164	
165	/** Chars-per-token used above. Exposed so the UI quotes the same number the docs do. */
166	const CHARS_PER_TOKEN = { svg: 3.2, base64: 3 } as const;
167	
168	/** Roughly what this logo adds to every turn of every build. */
169	export function logoTokenEstimate(logo: BrandLogo | null): number {
170	  if (!logo) return 0;
171	  return logo.format === "svg"
172	    ? Math.ceil(logo.markup.length / CHARS_PER_TOKEN.svg)
173	    : Math.ceil(logo.dataUri.length / CHARS_PER_TOKEN.base64);
174	}
