273	/**
274	 * A catalogue gradient turned into a full palette.
275	 *
276	 * primary/secondary are the gradient's own end stops, so "ocean" here is the
277	 * same ocean the find_assets tool returns to the builder. The accent is derived
278	 * rather than invented: the hue opposite the primary, at the primary's own
279	 * saturation and lightness, which gives a colour that reads as deliberate
280	 * against the pair without introducing a third brand decision the customer
281	 * never made.
282	 */
283	export function paletteFromPreset(presetId: string): BrandPalette | null {
284	  const preset: GradientPreset | undefined = GRADIENTS.find((g) => g.id === presetId);
285	  if (!preset) return null;
286	
287	  const primary = normalizeHex(preset.colors[0]);
288	  const secondary = normalizeHex(preset.colors[preset.colors.length - 1]);
289	  if (!primary || !secondary) return null;
290	
291	  // Three-stop presets (aurora) already ship a middle colour that was chosen to
292	  // sit between the ends; use it rather than computing one.
293	  const middle = preset.colors.length > 2 ? normalizeHex(preset.colors[1]) : null;
294	  const accent = middle ?? complement(primary);
295	
296	  const dark = luminance(primary) < 0.22 && luminance(secondary) < 0.22;
297	  return {
298	    presetId: preset.id,
299	    primary,
300	    secondary,
301	    accent,
302	    // A dark-family preset (midnight, ink, deep-sea) gets a dark surface; every
303	    // other preset stays on near-white, because a mid-tone page background is
304	    // where legibility goes to die.
305	    ink: dark ? "#f8fafc" : NEAR_BLACK,
306	    surface: dark ? "#0b1120" : "#ffffff",
