2	 * Reference-image handling for the portal composer.
3	 *
4	 * Deliberately a COPY of the downscale in components/marketing/PromptHero.tsx
5	 * (lines 44-57) rather than an import: that file belongs to the marketing
6	 * system and to another owner. The two must agree on one thing only — the
7	 * output has to be a `data:image/(png|jpeg|webp);base64,…` URL, because that
8	 * regex in app/api/generate/route.ts (line 57) is the sole gate. Anything else
9	 * is silently dropped server-side and the customer never learns their image
10	 * was ignored, so this module refuses it up front instead.
11	 */
12	
13	/** Exactly what app/api/generate/route.ts will accept. */
14	export const ACCEPTED_IMAGE_TYPES = ["image/png", "image/jpeg", "image/webp"] as const;
15	
16	/** What the file picker offers. Narrower than `image/*` on purpose — a HEIC
17	    from a phone would be offered by `image/*` and then fail to decode. */
18	export const IMAGE_ACCEPT = ".png,.jpg,.jpeg,.webp,image/png,image/jpeg,image/webp";
19	
20	export type ImageResult =
21	  | { ok: true; dataUrl: string; name: string; bytes: number }
22	  | { ok: false; error: string };
23	
24	/**
25	 * Downscale and re-encode to JPEG. Re-encoding is what makes the result
26	 * predictable: whatever came in, what goes out is `data:image/jpeg;base64,…`,
27	 * which the generate route accepts. It also keeps a 12MP phone photo from
28	 * costing a fortune in image tokens for detail the model cannot use.
29	 */
30	export async function prepareReferenceImage(
31	  file: File,
32	  maxDim = 1400,
33	  quality = 0.82,
34	): Promise<ImageResult> {
35	  if (!(ACCEPTED_IMAGE_TYPES as readonly string[]).includes(file.type)) {
36	    return {
37	      ok: false,
38	      error: "That file type can't be used as a reference. Pick a PNG, JPEG or WebP image.",
39	    };
40	  }
41	
42	  try {
43	    const bitmap = await createImageBitmap(file);
44	    const scale = Math.min(1, maxDim / Math.max(bitmap.width, bitmap.height));
45	    const w = Math.max(1, Math.round(bitmap.width * scale));
46	    const h = Math.max(1, Math.round(bitmap.height * scale));
47	    const canvas = document.createElement("canvas");
48	    canvas.width = w;
49	    canvas.height = h;
50	    const ctx = canvas.getContext("2d");
51	    if (!ctx) return { ok: false, error: "This browser couldn't read that image." };
52	    ctx.drawImage(bitmap, 0, 0, w, h);
53	    bitmap.close();
54	
55	    const dataUrl = canvas.toDataURL("image/jpeg", quality);
56	    if (!dataUrl.startsWith("data:image/jpeg;base64,")) {
57	      return { ok: false, error: "This browser couldn't re-encode that image." };
58	    }
59	    // Base64 of the payload, minus the `data:image/jpeg;base64,` prefix.
60	    const bytes = Math.round((dataUrl.length - 23) * 0.75);
61	    return { ok: true, dataUrl, name: file.name, bytes };
62	  } catch {
63	    return { ok: false, error: "That image couldn't be read. Try a different one." };
64	  }
65	}
