37	    <div
38	      role="radiogroup"
39	      aria-label={ariaLabel}
40	      className={`inline-flex items-center gap-0.5 rounded-md border border-hair bg-surface-2 p-0.5 ${className}`}
41	    >
42	      {options.map((o) => {
43	        const active = o.value === value;
44	        return (
45	          <label
46	            key={o.value}
47	            title={o.iconOnly ? o.label : undefined}
48	            className={[
49	              "relative inline-flex cursor-pointer items-center justify-center gap-1.5 rounded-[6px] px-2.5 text-[0.8125rem] font-medium",
50	              h,
51	              active
52	                ? "bg-surface text-ink shadow-e1"
53	                : "text-ink-2 hover:text-ink",
54	              "transition-colors duration-[var(--t-1)] has-[:focus-visible]:outline has-[:focus-visible]:outline-2 has-[:focus-visible]:outline-offset-2 has-[:focus-visible]:outline-[var(--brand-ring)]",
55	            ].join(" ")}
56	          >
57	            <input
58	              type="radio"
59	              name={name}
60	              value={o.value}
61	              checked={active}
62	              onChange={() => onChange(o.value)}
63	              className="sr-only"
64	            />
65	            {o.icon}
66	            {o.iconOnly ? <span className="sr-only">{o.label}</span> : o.label}
