10	   obvious next action, which is most of why it read as generic. */
11	const VARIANT: Record<ButtonVariant, string> = {
12	  // The only element in the product that carries the brand gradient as a
13	  // fill. `group` + the two .btn-* classes reuse the marketing CTA treatment
14	  // verbatim so the "Create Website" button feels like the same object the
15	  // customer clicked on the marketing site.
16	  primary:
17	    "group relative overflow-hidden text-white btn-cta-gradient shadow-e2 hover:shadow-e3 active:translate-y-px",
18	  secondary:
19	    "bg-surface text-ink border border-line-mid hover:bg-surface-2 hover:border-line-strong shadow-e1",
20	  ghost: "text-ink-2 hover:bg-surface-2 hover:text-ink",
21	  soft: "bg-brand-tint text-brand-ink hover:bg-brand-tint-2 dark:text-brand",
22	  danger: "bg-danger-tint text-danger hover:brightness-95 dark:hover:brightness-110",
23	};
24	
25	const SIZE: Record<ButtonSize, string> = {
26	  xs: "h-7 gap-1.5 px-2.5 text-xs rounded-sm",
27	  sm: "h-8 gap-1.5 px-3 text-[0.8125rem] rounded-md",
28	  md: "h-9.5 gap-2 px-4 text-sm rounded-md",
29	  lg: "h-11.5 gap-2 px-5 text-[0.9375rem] rounded-lg",
30	};
