3	export type StepState = "done" | "active" | "pending" | "failed";
4	export type ProgressStep = { id: string; label: string; state: StepState };
5	
6	/* THE single AI-progress component. The initial build overlay, the chat panel
7	   during an edit, and the preview's busy state all render this same list, so
8	   "Kodely is working" looks like one object the customer follows across three
9	   places rather than three unrelated spinners.
10	
11	   Why a step LIST and not a percentage: the build genuinely does not know how
12	   far along it is — it is an agent loop of unknown length — and a progress bar
13	   that jumps or stalls at 80% is a worse lie than an honest sequence of named
14	   steps. What it does know is which phase it is in, so that is what is shown.
15	
16	   Callers must drive `state` from real signals. A timer that walks the list
17	   forward on its own would be a fake, and would still be sitting on
18	   "Finalizing" long after a build had failed. */
19	export function AIProgress({
20	  steps,
21	  className = "",
22	}: {
23	  steps: ProgressStep[];
24	  className?: string;
25	}) {
26	  return (
27	    <ol
28	      className={`flex flex-col gap-2 ${className}`}
29	      // Each step's arrival is announced once as it changes, which is the
30	      // whole point of the component for a screen-reader user — they get the
31	      // same "it is working, here is where it is" that sighted users get.
32	      aria-live="polite"
33	      aria-atomic="false"
34	    >
35	      {steps.map((s, i) => (
36	        <li
37	          key={s.id}
38	          className="k-step-in flex items-center gap-2.5 text-[0.8125rem]"
39	          style={{ animationDelay: `${i * 55}ms` }}
40	        >
41	          <StepIcon state={s.state} />
42	          <span
43	            className={
44	              s.state === "pending"
45	                ? "text-ink-3"
46	                : s.state === "failed"
47	                  ? "text-danger"
48	                  : s.state === "active"
49	                    ? "font-medium text-ink"
50	                    : "text-ink-2"
