// ---------------------------------------------------------------------------
// Cleaning
// ---------------------------------------------------------------------------

/**
 * A single-line answer, safe to interpolate into a brief.
 *
 * Control characters and newlines go before the trim, not after: these values
 * land inside a prompt that is structured by line breaks, and a value carrying
 * its own newlines could restructure the sections around it. Same reasoning as
 * cleanBusinessName() in lib/brand-kit.ts.
 */
function line(value: string, max: number): string {
  return value
    .replace(/[�-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, max)
    .trim();
}

/** A multi-line answer: newlines survive, everything else is normalised, and
 *  blank lines collapse so a stray double return does not become a gap. */
function lines(value: string, max: number, maxLines = 12): string[] {
  return value
    .replace(/\r\n?/g, "\n")
    .replace(/[�-	 -]+/g, " ")
    .slice(0, max)
    .split("\n")
    .map((l) => l.replace(/[\s;,]+$/, "").trim())
    .filter(Boolean)
    .slice(0, maxLines);
}

/** "a bakery in Leeds." -> "a bakery in Leeds" — the opener supplies its own
 *  punctuation. Copied from lib/wizard.ts, which does not export it. */
function stripTrailingPunctuation(value: string): string {
  return value.replace(/[.!,;:—–-]+$/, "").trim();
}

/** The longest leading run of whole sentences that still fits in `max`. Falls
 *  back to a hard slice when the first sentence is itself too long. */
function firstSentences(value: string, max: number): string {
  if (value.length <= max) return value;
  const cut = value.slice(0, max);
  const stop = Math.max(cut.lastIndexOf(". "), cut.lastIndexOf("! "), cut.lastIndexOf("? "));
  if (stop > max * 0.4) return cut.slice(0, stop + 1).trim();
  const space = cut.lastIndexOf(" ");
  return (space > max * 0.5 ? cut.slice(0, space) : cut).trim();
}

// ---------------------------------------------------------------------------
// Assembly
// ---------------------------------------------------------------------------

/**
 * The opening line's subject, derived from what they typed on stage 1.
 *
 * lib/wizard.ts caps `whatYouDo` at 240 characters because it becomes the tail
 * of a single sentence. Stage 1 lets someone write considerably more than that,
 * so the opener takes the leading sentence or two and the full text is repeated
 * in its own block below. One sentence of overlap in a 2,000-character brief
 * reads as emphasis; truncating someone's description without telling them
 * would be a silent loss.
 */
function opener(describe: string): string {
  const clean = stripTrailingPunctuation(line(describe, LIMITS.describe));
  if (!clean) return "";
  return stripTrailingPunctuation(firstSentences(clean, 200));
}

function ownWordsBlock(describe: string): string {
  const clean = line(describe, LIMITS.describe);
  // Only worth repeating when the opener could not carry the whole thing.
  if (!clean || clean.length <= 200) return "";
  return `More about this business, in the owner's own words — treat it as the source of truth for what the site is for:\n${clean}`;
}

function factsBlock(a: InlineAnswers): string {
  const rows: string[] = [];
  const name = line(a.businessName, LIMITS.businessName);
  const location = line(a.location, LIMITS.location);
  const email = line(a.email, LIMITS.email);
  const phone = line(a.phone, LIMITS.phone);
  const offerings = lines(a.offerings, LIMITS.offerings);
  const hours = lines(a.hours, LIMITS.hours, 8);
  const links = lines(a.links, LIMITS.links, 8);

  if (name) rows.push(`- Name, spelled and capitalised exactly like this: ${name}`);
  if (location) rows.push(`- Where it is: ${location}`);
  if (offerings.length > 0) rows.push(`- What it offers: ${offerings.join("; ")}`);
  if (email) rows.push(`- Email address for enquiries: ${email}`);
  if (phone) rows.push(`- Phone number: ${phone}`);
  if (hours.length > 0) rows.push(`- Opening hours: ${hours.join(" · ")}`);
  if (links.length > 0) rows.push(`- Links to use: ${links.join(" · ")}`);

  if (rows.length === 0) return "";

  return [
    "These are the real details for this business. Use them exactly as written — in the copy, in the <title>, in the meta description, and in every call to action. Anything NOT in this list is something you do not know: leave it as an obvious bracketed placeholder such as [your address] rather than inventing a plausible-looking value.",
    ...rows,
  ].join("\n");
}

function toneBlock(tone: ToneId | null): string {
  const match = TONES.find((t) => t.id === tone);
  return match ? `Tone of voice for every word on the page: ${match.phrase}.` : "";
}

/**
 * Typography and density overrides.
 *
 * Placed after `assemblePrompt`'s look block on purpose — that block claims
 * precedence over hints EARLIER in the brief, so anything meant to beat it has
 * to come later and say so.
 */
function overridesBlock(a: InlineAnswers): string {
  const rows: string[] = [];
  if (a.typeFeel === "sans") {
    rows.push(
      "- Typography: the system sans stack throughout (ui-sans-serif, system-ui, sans-serif). No serif headings. Carry hierarchy with weight and size.",
    );
  }
  if (a.typeFeel === "serif") {
    rows.push(
      "- Typography: serif headings from the system serif stack (ui-serif, Georgia, serif) over a plain sans body. Remember there are no web fonts — the CSP allows none, base64 included.",
    );
  }
  if (a.density === "roomy") {
    rows.push(
      "- Density: roomy. A long vertical rhythm, roughly one idea per screen, generous whitespace, nothing crowded.",
    );
  }
  if (a.density === "compact") {
    rows.push(
      "- Density: compact. An obvious grid, even spacing, moderate type sizes, little idle space.",
    );
  }
  if (rows.length === 0) return "";
  return [
    "Two adjustments that override the visual direction above where they disagree with it:",
    ...rows,
  ].join("\n");
}

/**
 * What the attached logo actually is, said honestly.
 *
 * The image reaches the model as vision input (app/api/generate/route.ts passes
 * it through to lib/agent.ts, which labels it "visual/style guidance"). It is
 * never written into a file, and a generated site has no way to carry it: there
 * is no upload, and img-src allows only 'self' and data:. So the brief asks for
 * a marked space rather than for the logo, and the UI says the same thing.
 */
function logoBlock(a: InlineAnswers): string {
  if (!a.logo) return "";
  return [
    "I have attached my logo as the reference image for this build. Use it for the brand's colours, weight and general character — pull the palette towards it where that does not fight the visual direction above.",
    "Do NOT attempt to redraw the logo as SVG and do NOT reference the image file: you cannot embed it, and an approximation of somebody's logo is worse than none. In the header and the footer, leave a correctly-sized, clearly-bracketed [your logo] slot with the business name set in type beside it, so the space is ready when the real file goes in.",
  ].join(" ");
}

/**
 * Everything, as one string. Deterministic: the same answers always produce the
 * same prompt, which is what lets stage 5's Revert re-derive the text after an
 * edit is thrown away.
 */
export function assembleInlineBrief(a: InlineAnswers): string {
  const base: WizardAnswers = {
    category: a.category,
    templateId: a.templateId,
    businessName: line(a.businessName, LIMITS.businessName),
    whatYouDo: opener(a.describe),
    lookId: a.lookId,
  };

  return [
    assemblePrompt(base),
    overridesBlock(a),
    toneBlock(a.tone),
    ownWordsBlock(a.describe),
    factsBlock(a),
    featuresFragment(a.featureIds),
    logoBlock(a),
  ]
    .filter(Boolean)
    .join("\n\n")
    .trim();
}

/** True once the customer has told us anything at all. Drives the "you can go
 *  straight to the prompt" affordance and nothing else. */
export function hasInlineAnswers(a: InlineAnswers): boolean {
  return Boolean(
    a.describe.trim() ||
      a.category ||
      a.templateId ||
      a.businessName.trim() ||
      a.location.trim() ||
      a.offerings.trim() ||
      a.email.trim() ||
      a.phone.trim() ||
      a.hours.trim() ||
      a.links.trim() ||
      a.lookId ||
      a.tone ||
      a.typeFeel !== "look" ||
      a.density !== "look" ||
      a.logo ||
      a.featureIds.length > 0,
  );
}

