/**
 * Drop C0/C1 control characters, optionally keeping newlines.
 *
 * Written as a loop rather than a character-class regex for the reason
 * lib/brand-kit.ts's stripControls() spells out: a regex literal containing
 * control escapes trips `no-control-regex`, and disabling a rule that may not
 * be enabled is itself reported as an unused directive.
 */
function stripControls(value: string, keepNewlines: boolean): string {
  let out = "";
  for (const ch of value) {
    const c = ch.codePointAt(0) ?? 0;
    if (c === 0x0a) {
      out += keepNewlines ? "\n" : " ";
      continue;
    }
    if (c === 0x09 || c === 0x0d) {
      out += keepNewlines && c === 0x0d ? "" : " ";
      continue;
    }
    if (c < 0x20 || c === 0x7f || (c >= 0x80 && c <= 0x9f)) continue;
    out += ch;
  }
  return out;
}

/**
 * A single-line answer, safe to interpolate into a brief.
 *
 * Newlines are flattened rather than trimmed: these values land inside a prompt
 * that is structured by line breaks, and a value carrying its own newlines
 * could restructure the sections around it. Same reasoning as
 * cleanBusinessName() in lib/brand-kit.ts.
 */
function line(value: string, max: number): string {
  return stripControls(value, false).replace(/\s+/g, " ").trim().slice(0, max).trim();
}

/** A multi-line answer: newlines survive, everything else is normalised, and
 *  blank lines collapse so a stray double return does not become a gap. */
function lines(value: string, max: number, maxLines = 12): string[] {
  return stripControls(value, true)
    .slice(0, max)
    .split("\n")
    .map((l) => l.replace(/\s+/g, " ").replace(/[\s;,]+$/, "").trim())
    .filter(Boolean)
    .slice(0, maxLines);
}

